/**
 * A simple predator-prey simulator, based on a rectangular field
 * containing rabbits and foxes.
 *
 * @version 26/02/2022
 */
public class Simulator
{
    // Constants representing configuration information for the simulation.
    // The default width for the grid.
    private static final int DEFAULT_WIDTH = 270;
    // The default depth of the grid.
    private static final int DEFAULT_DEPTH = 180;
    // The probability that a lion will be created in any given grid position.
    private static final double LION_CREATION_PROBABILITY = 0.0125; //0.015
    // The probability that a cheetah will be created in any given grid position.
    private static final double CHEETAH_CREATION_PROBABILITY = 0.0125; //0.015
    // The probability that a zebra will be created in any given grid position.
    private static final double ZEBRA_CREATION_PROBABILITY = 0.08; //0.08
    // The probability that a giraffe will be created in any given grid position.
    private static final double GIRAFFE_CREATION_PROBABILITY = 0.08; //0.08
    // The probability that a giraffe will be created in any given grid position.
    private static final double LEMUR_CREATION_PROBABILITY = 0.081; //0.08

    // List of animals in the field.
    private List<LivingOrganism> animals;
    // List of plants in the field
    private List<LivingOrganism> plants;
    // The current state of the field.
    private Field field;
    // A graphical view of the simulation.
    private SimulatorView view;
    // List of buttons that are used to control the simulation.
    private JButton[] buttons;

    /**
     * Construct a simulation field with default size.
     */
    public Simulator()
    {
        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
    }

    /**
     * Create a simulation field with the given size.
     * @param depth Depth of the field. Must be greater than zero.
     * @param width Width of the field. Must be greater than zero.
     */
    public Simulator(int depth, int width)
    {
        if(width <= 0 || depth <= 0) {
            System.out.println("The dimensions must be greater than zero.");
            System.out.println("Using default values.");
            depth = DEFAULT_DEPTH;
            width = DEFAULT_WIDTH;
        }

        animals = new ArrayList<>();
        plants = new ArrayList<>();
        field = new Field(depth, width);
        buttons = new JButton[5];

        // Creates the buttons for the view
        JButton playPause = new JButton("Play");
            playPause.addActionListener(e -> new Thread(() -> playPauseButton()).start());
            buttons[0] = playPause;

        JButton runLongSim = new JButton("Run Long Sim");
            runLongSim.addActionListener(e -> new Thread(() -> runLongSimulation()).start());
            buttons[1] = runLongSim;

        JButton simOneStep = new JButton("Sim One Step");
            simOneStep.addActionListener(e -> simulateOneStep());
            buttons[2] = simOneStep;

        JButton reset = new JButton("Reset");
            reset.addActionListener(e -> reset());
            buttons[3] = reset;

        JButton quit = new JButton("Quit");
            quit.addActionListener(e -> quit());
            buttons[4] = quit;

        // Sets the visibility of the buttons in accordance to the current state of the simulation.
        buttonToggle();

        // Create a view of the state of each location in the field.
        view = new SimulatorView(depth, width, buttons);
        view.setColor(Zebra.class, Color.BLACK, Color.WHITE);
        view.setColor(Giraffe.class, Color.YELLOW, Color.BLACK);
        view.setColor(Lemur.class, Color.BLUE, Color.WHITE);
        view.setColor(Lion.class, Color.RED, Color.WHITE);
        view.setColor(Cheetah.class, Color.ORANGE, Color.BLACK);
        view.setColor(Plant.class, Color.GREEN, Color.BLACK);

        // Setup a valid starting point.
        reset();
    }

    /**
     * Controls the functionality of the Play/Pause button. This depends
     * on whether the simulation is paused or not.
     */
    private void playPauseButton() 
    {
        boolean isPaused = Time.getIsPaused();

        Time.toggleIsPaused();

        if (isPaused) {
            if (! Time.getIsFinished()) {
                simulate();
            }
        }

        buttonToggle();
    }

    /**
     * Run the simulation from its current state for a reasonably long 
     * period: 500 steps.
     */
    private void runLongSimulation()
    {
        simulate(500);
    }

    /**
     * Run the simulation from its current state for the given number of 
     * steps.
     * @param numSteps The number of steps to run for.
     */
    private void simulate(int numSteps)
    {
        // Sets the number of steps that the simulation run started at
        Time.setStepsToRunFor(numSteps);
        simulate();
    }

    /**
     * Run the simulation from its current state for the given number of 
     * steps in the Time Class.
     * Stop before the given number of steps if it ceases to be viable.
     * This is considered to be when only one species remains.
     */
    private void simulate() 
    {
        Time.setIsPaused(false);

        // Adjust button visibility.
        buttonToggle();

        while (! Time.getIsPaused() && ! Time.getIsFinished() && view.isViable(field)) {
            simulateOneStep();
        }

        Time.setIsPaused(true);
        buttonToggle();
    }

    /**
     * Run the simulation from its current state for a single step.
     * Iterate over the whole field updating the state of each
     * predator, prey, and plant.
     */
    private void simulateOneStep()
    {
        Time.incrementStep();
        Weather.updateWeather();

        // Provide space for newborn animals and plants;
        List<LivingOrganism> newAnimals = new ArrayList<>();
        List<LivingOrganism> newPlants = new ArrayList<>();

        // Let all animals act.
        for(Iterator<LivingOrganism> it = animals.iterator(); it.hasNext(); ) 
        {
            Animal animal = (Animal) it.next();

            if(animal != null) 
            {
                animal.act(newAnimals);

                if (! animal.isAlive())
                {
                    it.remove();
                }
            }
        }

        // Let all plants act.
        for(Iterator<LivingOrganism> it = plants.iterator(); it.hasNext(); ) {
            Plant plant = (Plant) it.next();
            if(plant != null) 
            {
                plant.act(newPlants);

                if (! plant.isAlive())
                {
                    it.remove();
                }
            }
        }

        // Add the newly born animals and plants to the main lists.
        animals.addAll(newAnimals);
        plants.addAll(newPlants); 

        // Show the current state in the view.
        view.showStatus(field);
    }

    /**
     * Reset the simulation to a starting position.
     */
    private void reset()
    {
        // Resets the visibility of the buttons and resets the step number
        Time.resetStep();
        buttonToggle();

        // Clears all current animals and plants then repopulates the area
        animals.clear();
        plants.clear();
        populate();

        // Show the starting state in the view.
        view.showStatus(field);
    }

    /**
     * Randomly populate the field with predators, prey, and plants.
     */
    private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) 
        {
            for(int col = 0; col < field.getWidth(); col++) 
            {
                //plants will fill the entire field initially.
                Location location = new Location(row, col);
                Plant plant = new Plant(true, field, location);
                plants.add(plant);

                Animal animal = null;

                if(rand.nextDouble() <= LION_CREATION_PROBABILITY) 
                {
                     animal = new Lion(true, field, location, false, false);
                }
                else if(rand.nextDouble() <= CHEETAH_CREATION_PROBABILITY)
                {
                     animal = new Cheetah(true, field, location, false, false);
                }
                else if(rand.nextDouble() <= ZEBRA_CREATION_PROBABILITY) 
                {
                     animal = new Zebra(true, field, location, false, false);
                }
                else if(rand.nextDouble() <= GIRAFFE_CREATION_PROBABILITY)
                {
                     animal = new Giraffe(true, field, location, false, false);
                }
                else if(rand.nextDouble() <= LEMUR_CREATION_PROBABILITY) 
                {
                     animal = new Lemur(true, field, location, false, false);
                }

                if(animal != null) 
                {
                    animals.add(animal);
                }
            }
        }
    }

    /**
     * Pause for a given time.
     * @param millisec  The time to pause for, in milliseconds
     */
    private void delay(int millisec)
    {
        try {
            Thread.sleep(millisec);
        }
        catch (InterruptedException ie) {
            // wake up
        }
    }

    /**
     * Sets the visibility of the buttons in accordance with the current
     * state of the simulation.
     */
    private void buttonToggle() 
    {
        boolean isPaused = Time.getIsPaused();
        boolean isFinished = Time.getIsFinished();

        boolean isStopped = false;
        if (isPaused || isFinished) 
        {
            isStopped = true;
        }

        // Adjust button usability.
        buttons[0].setEnabled(!isFinished);
        buttons[1].setEnabled(isStopped);
        buttons[2].setEnabled(isStopped);
        buttons[3].setEnabled(isStopped);

        // Set the label on the play/pause button.
        if (isStopped) 
        {
            buttons[0].setText("Play");   
        }
        else {
            buttons[0].setText("Pause");
        }
    }

    /**
     * Used by the quit button to close the application.
     */
    private void quit()
    {
        System.exit(0);
    }
}

import java.awt.*;
import javax.swing.*;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * A graphical view of the simulation grid.
 * The view displays a colored rectangle for each location 
 * representing its contents. It uses a default background color.
 * Colors for each type of species can be defined using the
 * setColor method.
 *
 * @version 26/02/2022
 */
public class SimulatorView extends JFrame
{
    // Colors used for empty locations.
    private static final Color EMPTY_COLOR = Color.white;

    // Color used for objects that have no defined color.
    private static final Color UNKNOWN_COLOR = Color.gray;

    private final String STEP_PREFIX = "  Step: ";
    private final String POPULATION_PREFIX = "Population: ";
    private final String TIME_PREFIX = "Time: ";
    private final String WEATHER_PREFIX = "Weather: ";
    private final String INFECTED_PREFIX = "Infected: ";
    private final String IMMUNE_PREFIX = "Immune: ";

    private JLabel stepLabel, population, infoLabel, timeLabel, 
                   weatherLabel, infectedLabel, immuneLabel;

    // The view of the simulation.
    private FieldView fieldView;

    // Stores a graph key which displays the colors of the classes.
    private JPanel classKey;

    // A map for storing colors for participants in the simulation
    private Map<Class<?>, Color> colors;

    // A statistics object computing and storing simulation information
    private FieldStats stats;

    /**
     * Create a view of the given width and height.
     * @param height The simulation's height.
     * @param width The simulation's width.
     * @param buttons The buttons used to control the simulation.
     */
    public SimulatorView(int height, int width, JButton[] buttons)
    {
        stats = new FieldStats();
        colors = new LinkedHashMap<>();

        setTitle("Savannah Simulation");
        stepLabel = new JLabel(STEP_PREFIX, JLabel.CENTER);
        population = new JLabel(POPULATION_PREFIX, JLabel.CENTER);
        timeLabel = new JLabel(TIME_PREFIX, JLabel.CENTER);
        weatherLabel = new JLabel(WEATHER_PREFIX, JLabel.CENTER);
        infectedLabel = new JLabel(INFECTED_PREFIX, JLabel.CENTER);
        immuneLabel = new JLabel(IMMUNE_PREFIX, JLabel.CENTER);

        fieldView = new FieldView(height, width);

        // Initialise all the JFrame elements        
        Container contents = getContentPane();

        // The menu bar at the top of the screen
        JMenuBar optionsBar = makeMenuBar();
            setJMenuBar(optionsBar);

        // The labels above the simulator
        JPanel infoPanel = new JPanel(new GridLayout());
            infoPanel.add(stepLabel);
            infoPanel.add(timeLabel);
            infoPanel.add(weatherLabel);

        classKey = new JPanel(new GridLayout());

        // The labels below the simulator
        JPanel populationPanel = new JPanel(new BorderLayout());
            populationPanel.add(classKey, BorderLayout.NORTH);
            populationPanel.add(infectedLabel, BorderLayout.WEST);
            populationPanel.add(population, BorderLayout.CENTER);
            populationPanel.add(immuneLabel, BorderLayout.EAST);

        // Adds the buttons to the side menu panel.
        JPanel menuPanel = new JPanel();
            menuPanel.setLayout(new BoxLayout(menuPanel, BoxLayout.Y_AXIS));
            for (int i = 0; i < buttons.length; i++) {
                buttons[i].setAlignmentX(Component.CENTER_ALIGNMENT);
                menuPanel.add(buttons[i]);
            }

        // add everything to the windows
        contents.add(infoPanel, BorderLayout.NORTH);
        contents.add(menuPanel, BorderLayout.WEST);
        contents.add(fieldView, BorderLayout.CENTER);
        contents.add(populationPanel, BorderLayout.SOUTH);

        pack();
        setVisible(true);
    }

    /**
     * Creates a menu bar at the top of the screen which different 
     * options.
     * @return Returns the new menu bar.
     */
    public JMenuBar makeMenuBar() {
        JMenuBar menuBar = new JMenuBar();

        JMenu menu;
        JMenuItem menuItem;

        menu = new JMenu("Help");
            menuBar.add(menu);

            menuItem = new JMenuItem("Instructions");
                menuItem.addActionListener(e -> showInstructions());
                menu.add(menuItem);

            menuItem = new JMenuItem("About");
                menuItem.addActionListener(e -> showAbout());
                menu.add(menuItem);

        return menuBar;
    }

    /**
     * Displays a new popup screen containing instructions on how
     * to use the simulation.
     */
    public void showInstructions() 
    {
        String dialogue = "How to use:\n" +
                          "   - Use 'Play/Pause' button to stop and resume the simulation whilst in progress.\n" +
                          "   - Use the 'Run Long Sim' button to show the 500 steps of the simulation.\n" +
                          "   - Use the 'Sim One Step' button to show the next step of the simulation.\n" +
                          "   - Use the 'Reset' button whilst paused/finished to generate a brand new random seed.\n" +
                          "   - Use the 'Quit' button to exit the application.";
        JOptionPane.showMessageDialog (this, dialogue, "Instructions", JOptionPane.INFORMATION_MESSAGE);
    }

    /**
     * Displays a new popup screen containing information about the
     * project.
     */
    private void showAbout()
    {
        String dialogue = "Project: Savannah Simulation which is predator-prey-simulation\n" +
                          "Authors: \n" +
                          "             based on foxes-and-rabbits by Michael KÃ¶lling and David J. Barnes.\n\n" + 
                          "This project is based on part of the material for chapter 10 of the book\n" + 
                          "         Objects First with Java - A Practical Introduction using BlueJ\n" +
                          "         Sixth edition\n" +
                          "         David J. Barnes and Michael KÃ¶lling\n" +
                          "         Pearson Education, 2016\n\n" +
                          "A predator-prey simulation involving 2 predators (Cheetahs and Lions),\n" + 
                          "3 prey (Lemurs, Giraffes, and Zebras), and grass in an enclosed rectangular\n" + 
                          "field.";
        JOptionPane.showMessageDialog (this, dialogue, "About", JOptionPane.INFORMATION_MESSAGE);
    }

    /**
     * Define a color to be used for the given class.
     *
     * @param newClass The new Class' object.
     * @param classColor The color to be used for the given class.
     * @param textColor The color to be used for the text in the class key.
     */
    public void setColor(Class<?> newClass, Color classColor, Color textColor)
    {
        colors.put(newClass, classColor);

        // Creates label of the appropriate color and text to be
        // displayed by the class key.
        JLabel newClassLabel = new JLabel(newClass.getName(), JLabel.CENTER);

        // Adjusts color of the label's text
        newClassLabel.setForeground(textColor);

        newClassLabel.setBackground(classColor);
        newClassLabel.setOpaque(true);

        classKey.add(newClassLabel);
    }

    /**
     * @param animalClass The class to get the colour of.
     * 
     * @return The color to be used for a given class of animal.
     */
    private Color getColor(Class<?> animalClass)
    {
        Color col = colors.get(animalClass);
        if(col == null) {
            // no color defined for this class
            return UNKNOWN_COLOR;
        }
        else {
            return col;
        }
    }

    /**
     * Show the current status of the field.
     * 
     * @param field The field whose status is to be displayed.
     */
    public void showStatus(Field field)
    {
        if(!isVisible()) {
            setVisible(true);
        }

        stepLabel.setText(STEP_PREFIX + Time.getStep());
        timeLabel.setText(TIME_PREFIX + getTimeString());
        weatherLabel.setText(WEATHER_PREFIX + Weather.getWeather() + "  ");
        stats.reset();

        fieldView.preparePaint();

        // Used to tally up the respective counts.
        int numberOfInfected = 0;
        int numberOfImmune = 0;

        for(int row = 0; row < field.getDepth(); row++) 
        {
            for(int col = 0; col < field.getWidth(); col++) 
            {
                Animal animal = field.getObjectAt(row, col, Animal.class);
                Plant plant = field.getObjectAt(row, col, Plant.class);

                if(animal != null) 
                {
                    stats.incrementCount(animal.getClass());
                    fieldView.drawMark(col, row, getColor(animal.getClass()));

                    // Update the infected and immune counts
                    if (animal.getIsInfected())
                    {
                        numberOfInfected++;
                    }

                    if (animal.getIsImmune())
                    {
                        numberOfImmune++;
                    }
                }
                // Only show the plant if an animal is not present
                else if(plant != null) 
                {
                    fieldView.drawMark(col, row, getColor(plant.getClass()));
                }
                else 
                {
                    Color emptyColor = EMPTY_COLOR;
                    fieldView.drawMark(col, row, emptyColor);
                    fieldView.setBackground(emptyColor);
                }

                if (plant != null) 
                {
                   stats.incrementCount(plant.getClass()); 
                }
            }
        }

        stats.countFinished();

        infectedLabel.setText(INFECTED_PREFIX + numberOfInfected);
        immuneLabel.setText(IMMUNE_PREFIX + numberOfImmune);

        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
        fieldView.repaint();
    }

    /**
     * Determine whether the simulation should continue to run.
     * 
     * @param field The field to check viability.
     *
     * @return True if there is more than one species alive.
     */
    public boolean isViable(Field field)
    {
        return stats.isViable(field);
    }

    /**
     * @return Returns the properly formated time in 24 hr format.
     */
    private String getTimeString()
    {
        int time = Time.getTime();
        if (time >= 12){
            return time + ":00 ";
        }
        else {
            if(time<10){
                return "0" + time + ":00 ";
            }
            else {
                return time + ":00 ";
            }
        }
    }

    /**
     * Provide a graphical view of a rectangular field. This is 
     * a nested class (a class defined inside a class) which
     * defines a custom component for the user interface. This
     * component displays the field.
     */
    private class FieldView extends JPanel
    {
        private final int GRID_VIEW_SCALING_FACTOR = 6;

        private int gridWidth, gridHeight;
        private double xScale, yScale;
        Dimension size;
        private Graphics g;
        private Image fieldImage;

        /**
         * Create a new FieldView component.
         */
        public FieldView(int height, int width)
        {
            gridHeight = height;
            gridWidth = width;
            size = new Dimension(0, 0);
        }

        /**
         * Tell the GUI manager how big we would like to be.
         * 
         * @return Dimensions
         */
        public Dimension getPreferredSize()
        {
            return new Dimension(gridWidth * GRID_VIEW_SCALING_FACTOR,
                                 gridHeight * GRID_VIEW_SCALING_FACTOR);
        }

        /**
         * Prepare for a new round of painting. Since the component
         * may be resized, compute the scaling factor again.
         */
        public void preparePaint()
        {
            if(! size.equals(getSize())) {  // if the size has changed...
                size = getSize();
                fieldImage = fieldView.createImage(size.width, size.height);
                g = fieldImage.getGraphics();

                xScale = size.width / gridWidth;
                if(xScale < 1) {
                    xScale = GRID_VIEW_SCALING_FACTOR;
                }
                yScale = size.height / gridHeight;
                if(yScale < 1) {
                    yScale = GRID_VIEW_SCALING_FACTOR;
                }

                // Makes sure that the grid remains in proportion
                // (the grid squares remain as squares)
                if(xScale > yScale) {
                    xScale = yScale;
                }
                else if(xScale < yScale) {
                    yScale = xScale;
                }
            }
        }

        /**
         * Paint on grid location on this field in a given color.

         * @param x X-position to draw the mark
         * @param y Y-position to draw the mark
         * @param color The colour to draw the mark
         */
        private void drawMark(int x, int y, Color color)
        {
            g.setColor(color);
            g.fillRect((int)(x * xScale), (int)(y * yScale) , (int)(xScale - 1.0), (int)(yScale - 1.0));
        }

        /**
         * The field view component needs to be redisplayed. Copy the
         * internal image to screen.
         * 
         * @param g Graphics
         */
        public void paintComponent(Graphics g)
        {
            if(fieldImage != null) 
            {
                Dimension currentSize = getSize();

                if(size.equals(currentSize)) 
                {
                    g.drawImage(fieldImage, 0, 0, null);
                }
                else 
                {
                    // Rescale the previous image.
                    g.drawImage(fieldImage, 0, 0, currentSize.width, currentSize.height, null);
                }
            }
        }
    }
}

import java.util.Random;
import java.util.List;

/**
 * A class representing the shared characteristics between Living Organisms.
 *
 * @version 26/02/2022
 */
public abstract class LivingOrganism
{
    // Whether the organism is alive or not.
    protected boolean alive;
    // The field the organism is stored in.
    protected Field field;
    // The organism's position in the field.
    protected Location location;
    // The food value of itself - how much the hunter's food level increases when eating it.
    protected int foodValue;

    // A shared random number generator to control breeding.
    protected static final Random rand = Randomizer.getRandom();

    /**
     * Creates a new Organism at the location.
     * 
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    protected LivingOrganism(Field field, Location location) 
    {
        alive = true;
        this.field = field;
        setLocation(location);
    }

    /**
     * Increments the organism's age.
     */
    protected abstract void incrementAge();

    /**
     * Make this organism act - that is: make it do
     * whatever it wants/needs to do.
     * 
     * @param newOrganisms A list to receive newly born organsims.
     */
    protected abstract void act(List<LivingOrganism> newOrganisms);

    /**
     * Check whether the organism is alive or not.
     * @return true if the organism is still alive.
     */
    protected boolean isAlive()
    {
        return alive;
    }

    /**
     * Indicate that the organism is no longer alive.
     * It is removed from the field.
     */
    protected abstract void setDead();

    /**
     * When called, the organism gets eaten and returns the
     * food value of which the organism eating it increases
     * 
     * @return The food value of the organism being eaten.
     */
    protected abstract int beEaten();

    /**
     * Return the organism's location.
     * @return The organism's location.
     */
    protected Location getLocation()
    {
        return location;
    }

    /**
     * Place the organism at the new location in the given field.
     * 
     * @param newLocation The organism's new location.
     */
    protected abstract void setLocation(Location newLocation);

    /**
     * Check whether or not this Organism is to give birth at this step.
     * New births will be made into free adjacent locations.
     * 
     * @param newOrganisms A list to return newly born Organisms.
     */
    protected abstract void populate(List<LivingOrganism> newOrganisms);

    /**
     * Return the organism's field.
     * 
     * @return The organism's field.
     */
    protected Field getField()
    {
        return field;
    }
}




import java.util.List;
import java.util.Iterator;
/**
 * A class representing shared characteristics of animals.
 *
 * @version 25/02/2022
 */
public abstract class Animal extends LivingOrganism
{
    // Indicates whether an animal is a female or not;
    protected boolean isFemale;
    // The age at which an animal can start to breed.
    protected int breedingAge;
    // The age to which an animal can live.
    protected int maxAge;
    // The likelihood of an animal breeding.
    protected double breedingProbability;
    // whther the animal is infected or not
    protected boolean infected;
    // The likelihood of an animal having a disease.
    protected double diseaseProbability;
    // The likelihood of an animal catching a disease from another animal
    protected double diseaseSpreadProbability;
    // The likelihood of an animal dying from catching the disease
    protected double deathFromInfectionProbability;
    // The likelihood of an animal becomming immune to the disease
    protected double immuneProbability;
    // whether the animal is immune or not
    protected boolean immune;
    // The maximum number of births.
    protected int maxLitterSize;
    // The animals's age.
    protected int age;
    // The animals's food level, which is increased by eating prey.
    protected int foodLevel;
    // The maximum food level that an animal will eat at. The food level they will stop
    // being hungry at
