                        spreadProbability = 0.14;
                        break;
                    case Foggy:
                        spreadProbability = 0.05;
                        break;
                    case Cloudy:
                        spreadProbability = 0.1;
                        break;
                    case Clear:
                        spreadProbability = 0.08;
                        break;
